import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { payload12Schema, type Payload12 } from "./payload12.js";
import { reportTypeSchema, type ReportType } from "./report-type.js";
import { requestStatusSchema, type RequestStatus } from "./request-status.js";

export type RequestStatusResponse = {
  /** Automated ID generated by system that uniquely identifies the report request. */
  requestId?: string;
  /** Status of report request. Possible values are RECEIVED, INPROGRESS, READY, ERROR. */
  requestStatus?: RequestStatus;
  /** Date and time on which the report request is submitted. */
  requestSubmissionDate?: string;
  /** Type of report for which the request is created. Example, ITEM for Item Report. */
  reportType?: ReportType;
  /** Version of report for which the request is created. Example, v1. */
  reportVersion?: string;
  /** Request Payload */
  payload?: Payload12;
  /**
   * Date and time on which the report is generated. Attribute is available only if report is
   * generated.
   */
  reportGenerationDate?: string;
};

export const requestStatusResponseSchema: Schema<RequestStatusResponse> = s.object<RequestStatusResponse>({
  requestId: s.optional(s.string()),
  requestStatus: s.optional(s.lazy(() => requestStatusSchema)),
  requestSubmissionDate: s.optional(s.string()),
  reportType: s.optional(s.lazy(() => reportTypeSchema)),
  reportVersion: s.optional(s.string()),
  payload: s.optional(s.lazy(() => payload12Schema)),
  reportGenerationDate: s.optional(s.string()),
});
